// The Moon map's zoom 5–6 tiles (F25), delivered by Play Asset Delivery only when the user asks for
// them. The tiles are generated by core/map/tools/build_moon_tiles.sh and checked in; nothing is
// built here. APK builds (assembleDebug) leave on-demand packs out; bundles carry them.
plugins {
    alias(libs.plugins.android.asset.pack)
}

assetPack {
    packName.set("moon_tiles_deep")
    dynamicDelivery {
        deliveryType.set("on-demand")
    }
}
